('agspr', 'Fields', 'searchfor', 'Search For*', 'c', '50', '0', 'select', NULL, NULL, NULL, NULL, 'select cast(sf as varchar(50)),fname,fromdt,todt,ordno,dcname,slno from(
select cast(period as varchar(50))as sf,period as fname,fromdt,todt,1 as ordno,null as dcname, 1 as slno from (
select ''As on today'' as period,''current_date''  as fromdt,''current_date'' as todt from dual
           union all
           select ''As of yesterday'' as period,''current_date-1'' as fromdt,''current_date-1'' as dt from dual
           union all
           select ''As of this month'' as period,''date_trunc(''''month'''',current_date)'' as fromdt ,''current_date'' as todt from dual
            union all
           select ''As of this week'' as period,''date_trunc(''''week'''',current_date)'' as fromdt ,''current_date'' as todt from dual
            union all
           select ''As of last month'' as period,''date_trunc(''''month'''',(add_months(current_date,0-1)))'' as fromdt ,''date_trunc(''''month'''', current_date) + interval ''''0 month'''' - interval ''''1 day'''''' as todt from dual
            union all
           select ''As of last week'' as period,''date_trunc(''''week'''',current_date-7)'' as fromdt ,''date_trunc(''''week'''',current_date-7)+ interval ''''6 day'''''' as todt from dual
) a where :hltype =''iview'' and :periodically = ''T''
union all
select ''NA'' AS SF,''NA'' fname,null as fromdt,null as todt,0 ordno,null as dcname,2 as slno from dual where   ( :action = ''Open''  )
union all
select ''link'' AS SF,''link'' fname,null as fromdt,null as todt,0 ordno,null as dcname,2 as slno from dual where   (  :hltype = ''help'' )
union all
select caption||''(''|| fname ||'')'' as sf,fname,null as fromdt,null as todt,ordno,dcname,3 as slno from axpflds where  savevalue=''T'' and asgrid=''F'' and tstruct= :structname and :hltype <> ''iview'' 
AND  ( COALESCE(allowduplicate,''T'')=''F'' or lower(modeofentry)=''autogenerate'') and   :periodically =''F''
union all
select caption||''(''|| fname ||'')'' as sf,fname,null as fromdt,null as todt,ordno,dcname,4 as slno from axpflds where  savevalue=''T'' and asgrid=''F'' and tstruct= :structname and :hltype <> ''iview'' 
AND  ( COALESCE(allowduplicate,''T'')=''T'' and lower(modeofentry)<>''autogenerate'') and   :periodically =''F''
union all
  select  pcaption||''(''|| pname ||'')'' as sf, pname,null as fromdt,null as todt,1 as ordno,null dcname,5 as slno from iviewparams where iname= :structname  
and :hltype = ''iview'' and :periodically = ''F''
and moe in (''Select'',''Accept'',''Pick List''))x
order by slno,ordno
